	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

func runDiff(args []string) int {
	fs := flag.NewFlagSet("diff", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	oldPath := fs.String("old", "", "path to old spec file")
	newPath := fs.String("new", "", "path to new spec file")
	if err := fs.Parse(args); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 2
	}
	if *oldPath == "" {
		fmt.Fprintln(os.Stderr, "error: missing --old")
		return 2
	}
	if *newPath == "" {
		fmt.Fprintln(os.Stderr, "error: missing --new")
		return 2
	}
	if len(fs.Args()) > 0 {
		fmt.Fprintf(os.Stderr, "error: unexpected argument: %s\n", fs.Args()[0])
		return 2
	}

	oldSpec, err := loadSpec(*oldPath)
	if err != nil {
		printDiffValidationError("old: ", err)
		return 2
	}
	newSpec, err := loadSpec(*newPath)
	if err != nil {
		printDiffValidationError("new: ", err)
		return 2
	}

	if canonicalForm(oldSpec) == canonicalForm(newSpec) {
		return 0
	}

	oldTuples := jobTuples(oldSpec)
	newTuples := jobTuples(newSpec)

	oldByName := make(map[string]diffJob, len(oldTuples))
	for _, t := range oldTuples {
		oldByName[t.name] = t
	}
	newByName := make(map[string]diffJob, len(newTuples))
	for _, t := range newTuples {
		newByName[t.name] = t
	}

	var out strings.Builder
	for _, t := range newTuples {
		if _, ok := oldByName[t.name]; !ok {
			fmt.Fprintf(&out, "+ %s\n", t.name)
		}
	}
	for _, t := range oldTuples {
		if _, ok := newByName[t.name]; !ok {
			fmt.Fprintf(&out, "- %s\n", t.name)
		}
	}
	for _, t := range newTuples {
		old, ok := oldByName[t.name]
		if !ok {
			continue
		}
		if old.workdir != t.workdir {
			fmt.Fprintf(&out, "~ %s workdir: %s -> %s\n", t.name, old.workdir, t.workdir)
		}
		if old.command != t.command {
			fmt.Fprintf(&out, "~ %s command: %s -> %s\n", t.name, old.command, t.command)
		}
		if reprDeps(old.deps) != reprDeps(t.deps) {
			fmt.Fprintf(&out, "~ %s deps: %s -> %s\n", t.name, reprDeps(old.deps), reprDeps(t.deps))
		}
		if reprEnv(old.env) != reprEnv(t.env) {
			fmt.Fprintf(&out, "~ %s env: %s -> %s\n", t.name, reprEnv(old.env), reprEnv(t.env))
		}
		if old.level != t.level {
			fmt.Fprintf(&out, "~ %s level: %s -> %s\n", t.name, reprLevel(old.level), reprLevel(t.level))
		}
	}

	if out.Len() == 0 {
		return 0
	}
	fmt.Print(out.String())
	return 1
}

type diffJob struct {
	name    string
	workdir string
	command string
	deps    []string
	env     []string
	level   int
}

func jobTuples(spec *Spec) []diffJob {
	levels := computeLevels(spec)
	var tuples []diffJob
	for level, names := range levels {
		for _, name := range names {
			job := spec.ByName[name]
			envKeys := make([]string, 0, len(job.Env))
			for k := range job.Env {
				envKeys = append(envKeys, k)
			}
			sort.Strings(envKeys)
			envParts := make([]string, 0, len(envKeys))
			for _, k := range envKeys {
				envParts = append(envParts, k+"="+job.Env[k])
			}
			tuples = append(tuples, diffJob{
				name:    job.Name,
				workdir: job.Workdir,
				command: job.Command,
				deps:    job.Deps,
				env:     envParts,
				level:   level,
			})
		}
	}
	return tuples
}

func reprDeps(deps []string) string {
	return "[" + strings.Join(deps, ",") + "]"
}

func reprEnv(parts []string) string {
	return "{" + strings.Join(parts, ",") + "}"
}

func reprLevel(level int) string {
	return strconv.Itoa(level)
}

func printDiffValidationError(prefix string, err error) {
	if ve, ok := err.(*ValidationError); ok {
		fmt.Fprintf(os.Stderr, "error: %s%s: %s\n", prefix, ve.Code, ve.Message)
		return
	}
	fmt.Fprintf(os.Stderr, "error: %s%s\n", prefix, err)
}
